(async()=>{if(!document.getElementById('work-rows'))return;const u=EamWorkUi,$=u.$,api=EamProblemApi;let orders=[],candidates=[],page=1,createKey='',busy=false;
function draw(){const filtered=orders.filter(o=>(!$('work-search').value||[o.id,o.title,o.scope].join(' ').includes($('work-search').value))&&(!$('work-status').value||o.status===$('work-status').value)&&(!$('work-mine').checked||o.assigneeId===Eam.s.person));const pages=Math.max(1,Math.ceil(filtered.length/8));page=Math.min(page,pages);$('work-rows').replaceChildren();for(const o of filtered.slice((page-1)*8,page*8)){const title=u.link('',()=>Eam.go('order',{order:o.id}));title.append(u.node('strong',o.id+' · '+o.title),u.node('small',o.scope));const refs=u.node('div');refs.textContent=o.problemRefs.length+'项问题';refs.append(u.node('small',o.problemRefs.map(p=>p.id).join(' / ')));const actions=u.node('div',undefined,'actions');actions.append(u.button(o.status==='technical_complete'?'技术验收':'查看工单',()=>Eam.go(o.status==='technical_complete'?'acceptance':'order',{order:o.id})));u.row($('work-rows'),[title,refs,u.name(o.assigneeId),u.badge(o.status),'V'+o.executionVersion,actions],['工单 / 范围','关联问题','执行人','状态','执行版本','操作']);}$('work-total').textContent=orders.length;$('work-active').textContent=orders.filter(o=>['executing','paused'].includes(o.status)).length;$('work-review').textContent=orders.filter(o=>o.status==='technical_complete').length;$('work-close').textContent=orders.filter(o=>o.status==='accepted').length;$('work-empty').hidden=!!filtered.length;$('work-count').textContent=EamUiComponents.paginationText(filtered.length,page,pages);$('work-prev').disabled=page===1;$('work-next').disabled=page===pages;EamUiComponents.pagination($('work-count').parentElement,{page,pages:pages,total:filtered.length,pageSize:8,countId:'work-count',previousId:'work-prev',nextId:'work-next',onChange:nextPage=>{page=nextPage;draw();}});EamUiComponents.syncTableState($('work-rows').closest('table'));}
async function load(){EamUiComponents.setTableStatus('work-rows','loading');$('work-load').textContent='正在读取…';$('work-rows').inert=true;try{orders=EamArchiveContext.filter((await api.request('GET','/work-orders')).rows,location.search);draw();$('work-load').textContent='已读取 · '+orders.length+'条范围工单';EamUiComponents.setTableStatus('work-rows',orders.length?'loaded':'empty',$('work-load').textContent);}catch(e){$('work-load').textContent=e.message;$('work-rows').replaceChildren();EamUiComponents.setTableStatus('work-rows','error',e.message,load);}finally{$('work-rows').inert=false;}}
function candidateFilter(){for(const label of $('candidate-list').children)label.hidden=!label.textContent.includes($('candidate-search').value);}
async function create(){try{candidates=(await api.request('GET','/work-order-candidates')).rows;$('create-work-form').reset();const eq=new URLSearchParams(location.search).get('equipment');if(eq)$('work-equipment').value=eq;$('work-equipment').dispatchEvent(new Event('change'));candidates=EamArchiveContext.filter(candidates,location.search);createKey=crypto.randomUUID();$('candidate-list').replaceChildren();const q=new URLSearchParams(location.search);for(const p of candidates){const label=u.node('label',undefined,'work-candidate'),check=u.node('input');check.type='checkbox';check.dataset.kind=p.kind;check.value=p.id;check.checked=q.get('problemKind')===p.kind&&q.get('problemId')===p.id;const text=u.node('span');text.append(u.node('strong',p.id+' · '+p.description),u.node('small',u.label(p.status)+' · '+u.label(p.priority)));label.append(check,text);$('candidate-list').append(label);}$('work-create-error').textContent='';$('create-work-dialog').showModal();}catch(e){Eam.message(e.message);}}
$('create-work-form').onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;$('work-create-submit').disabled=true;try{const result=await api.request('POST','/work-orders',{idempotencyKey:createKey,equipmentId:$('work-equipment').value,title:$('work-title').value,scope:$('work-scope').value,scopeType:$('work-scope-type').value,permitId:$('work-permit').value,dueAt:$('work-due').value,reason:$('work-reason').value,problemRefs:[...$('candidate-list').querySelectorAll('input:checked')].map(x=>({kind:x.dataset.kind,id:x.value}))});$('create-work-dialog').close();Eam.go('order',{order:result.id,equipment:$('work-equipment').value});}catch(error){$('work-create-error').textContent=error.message+'；输入已保留。';}finally{busy=false;$('work-create-submit').disabled=false;}};
$('work-refresh').onclick=load;$('create-work').onclick=create;$('create-work').disabled=!['engineer','supervisor'].includes(Eam.s.role);$('work-create-cancel').onclick=()=>$('create-work-dialog').close();$('candidate-search').oninput=candidateFilter;for(const id of ['work-search','work-status','work-mine'])$(id).addEventListener(id==='work-search'?'input':'change',()=>{page=1;draw();});$('work-clear').onclick=()=>{$('work-search').value='';$('work-status').value='';$('work-mine').checked=false;page=1;draw();};$('work-prev').onclick=()=>{page--;draw();};$('work-next').onclick=()=>{page++;draw();};
try{const config=await u.init();for(const value of ['draft','approved','assigned','executing','paused','technical_complete','accepted','closed','cancelled'])$('work-status').add(new Option(u.label(value),value));const equipment=(await api.request('GET','/equipment')).rows;for(const e of equipment)$('work-equipment').add(new Option(e.name,e.id));for(const type of config.scopeTypes)$('work-scope-type').add(new Option(type.name,type.id));const permits=()=>{$('work-permit').replaceChildren();for(const p of config.permits.filter(p=>p.equipmentId===$('work-equipment').value&&p.scopeType===$('work-scope-type').value))$('work-permit').add(new Option(p.name,p.id));};$('work-equipment').onchange=permits;$('work-scope-type').onchange=permits;permits();await load();if(new URLSearchParams(location.search).get('create')&&$('create-work').disabled===false)await create();}catch(e){$('work-load').textContent=e.message;EamUiComponents.setTableStatus('work-rows','error',e.message,()=>location.reload());}
})();
